#include <WiFi.h>
#include <WebServer.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_BME280.h>

// WiFi Weather Station
// Temperature, humidity, and pressure on an OLED and a local webpage.

const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";
const float SEA_LEVEL_HPA = 1013.25; // standard reference pressure for altitude estimate

Adafruit_BME280 bme;
Adafruit_SSD1306 display(128, 64, &Wire, -1);
WebServer server(80);

void setup() {
  bme.begin(0x76); // try 0x77 if your board doesn't respond on 0x76
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);

  Serial.begin(115200);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }
  Serial.print("Weather station: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.begin();
}

void loop() {
  server.handleClient();
  updateDisplay();
  delay(1000);
}

void updateDisplay() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("Temp: "); display.print(bme.readTemperature(), 1); display.println(" C");
  display.print("Humidity: "); display.print(bme.readHumidity(), 0); display.println(" %");
  display.print("Pressure: "); display.print(bme.readPressure() / 100.0F, 0); display.println(" hPa");
  display.print("Altitude: "); display.print(bme.readAltitude(SEA_LEVEL_HPA), 0); display.println(" m");
  display.display();
}

void handleRoot() {
  String page = "<h1>Weather Station</h1>";
  page += "<p>Temperature: " + String(bme.readTemperature(), 1) + " &deg;C</p>";
  page += "<p>Humidity: " + String(bme.readHumidity(), 0) + " %</p>";
  page += "<p>Pressure: " + String(bme.readPressure() / 100.0F, 0) + " hPa</p>";
  page += "<p>Estimated altitude: " + String(bme.readAltitude(SEA_LEVEL_HPA), 0) + " m</p>";
  page += "<p><a href='/'>Refresh</a></p>";
  server.send(200, "text/html", page);
}
